// Helper function to get interest count for an event
export const getEventInterestCount = async (eventId: string): Promise<number> => {
  try {
    const { count, error } = await supabase
      .from("event_attendees")
      .select("*", { count: "exact", head: true })
      .eq("event_id", eventId)
      .is("check_in_time", null);
      
    if (error) {
      console.error("Error fetching interest count:", error);
      return 0;
    }
    
    return count || 0;
  } catch (error) {
    console.error("Error in getEventInterestCount:", error);
    return 0;
  }
};

// Helper function to check if a user is interested in an event
export const isUserInterestedInEvent = async (eventId: string, userId: string): Promise<boolean> => {
  if (!eventId || !userId) return false;
  
  try {
    const { data, error } = await supabase
      .from("event_attendees")
      .select("*")
      .eq("event_id", eventId)
      .eq("user_id", userId)
      .is("check_in_time", null)
      .maybeSingle();
      
    if (error) {
      console.error("Error checking interest:", error);
      return false;
    }
    
    return data !== null;
  } catch (error) {
    console.error("Error in isUserInterestedInEvent:", error);
    return false;
  }
};
